const stops=parseCSV('outputs/t05_clean_stops.csv');
const tts=parseCSV('outputs/t05_clean_stop_times.csv');
const trips=parseCSVString(execSync('unzip -p inputs/gtfs/sample_city_gtfs.zip trips.txt').toString());

const routeByTrip={};
const tripIdx=trips.header.indexOf('trip_id');
const routeIdx=trips.header.indexOf('route_id');
for(const r of trips.rows){routeByTrip[r[tripIdx]]=r[routeIdx];}

const res={};
const idIdx=stops.header.indexOf('stop_id');
const nameIdx=stops.header.indexOf('stop_name');
const latIdx=stops.header.indexOf('stop_lat');
const lonIdx=stops.header.indexOf('stop_lon');
for(const s of stops.rows){const id=s[idIdx];res[id]={id,name:s[nameIdx],lat:s[latIdx],lon:s[lonIdx],n_dep:0,routes:new Set(),first:'23:59:59',last:'00:00:00'};}

const ttsIdIdx=tts.header.indexOf('stop_id');
const depIdx=tts.header.indexOf('departure_time');
const tripIdxTts=tts.header.indexOf('trip_id');
for(const t of tts.rows){const id=t[ttsIdIdx];const dep=t[depIdx];const trip=t[tripIdxTts];const route=routeByTrip[trip];if(!res[id])continue;const obj=res[id];obj.n_dep++;if(dep<obj.first)obj.first=dep;if(dep>obj.last)obj.last=dep;obj.routes.add(route);}

const header='stop_id,stop_name,stop_lat,stop_lon,n_departures,n_routes,first_departure,last_departure';
const lines=[header];
for(const key in res){const o=res[key];lines.push([o.id,o.name,o.lat,o.lon,o.n_dep,o.routes.size,o.first,o.last].join(','));}
fs.writeFileSync('outputs/t06_stop_service_intensity.csv',lines.join('\n'),'utf8');
